CREATE TABLE IF NOT EXISTS "tickets" (
  "id" TEXT PRIMARY KEY,
  "notion_id" TEXT,
  "ticket_number" TEXT,
  "category_type" TEXT,
  "status" TEXT,
  "solution" TEXT,
  "reception_date" DATE,
  "receiver" TEXT,
  "created_at" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS "circulars" (
  "id" TEXT PRIMARY KEY,
  "title" TEXT,
  "number" TEXT,
  "description" TEXT,
  "file" TEXT,
  "date" TEXT,
  "color" TEXT,
  "created_at" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS "push_subscriptions" (
  "id" TEXT PRIMARY KEY,
  "subscription" JSONB,
  "user_name" TEXT,
  "created_at" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS "employees" (
  "name" TEXT PRIMARY KEY,
  "user" TEXT,
  "phone" TEXT,
  "pass" TEXT,
  "permissions" JSONB,
  "created_at" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS "employee_leaves" (
  "id" TEXT PRIMARY KEY,
  "employee_name" TEXT,
  "start_date" TEXT,
  "end_date" TEXT,
  "created_at" TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

